  "verdict": "reject",
  "findings": [
    {
      "severity": "High",
      "file": "scripts/software_study_harness.py",
      "issue": "In `BasicCell._apply`, model non-compliance (such as exceeding byte ceilings, omitting `test_argv`, or missing required files) raises `StudyHarnessError`. Because network requests are durably cached by `job_id`, this unhandled exception permanently bricks the cell on retry, crashing the study framework instead of properly recording the model's failure.",
      "fix": "Catch model-level format and compliance violations within `_apply` and gracefully transition the cell's state to 'failed' (e.g., `state['complete'] = True`), rather than raising a system-level exception that halts the runner."
    },
    {
      "severity": "High",
      "file": "scripts/software_study_harness.py",
      "issue": "In `BasicCell._request`, if the model's executed test naturally produces more than 4000 bytes of output (e.g. infinite loop or verbose logging), `encoded_contribution(text)>4000` raises `StudyHarnessError`. This check occurs during request preparation, causing a verbose test failure to fatally crash the harness and permanently brick the cell.",
      "fix": "Safely truncate the test output streams to the maximum allowed byte length before encoding, rather than raising an infrastructure exception that destroys cell progression."
    },
    {
      "severity": "High",
      "file": "scripts/study_cell_budget.py",
      "issue": "When a model exhausts its budget (exceeding `max_calls`/`max_total_input_bytes`) or returns identical unchanged code in the repair stage, `CellBudget` raises `StudyBudgetError`. These exceptions are not caught by the `BasicCell` runner, causing budget enforcements to crash the main harness process rather than failing the specific cell.",
      "fix": "Handle `StudyBudgetError` inside `BasicCell.step()` to gracefully finalize the cell with a failing grade and error classification, isolating budget enforcement from overall framework stability."
    },
    {
      "severity": "High",
      "file": "scripts/software_study_harness.py",
      "issue": "In `ToolkitCell.step()`, the final review preparation iterates over all historical test records and verifies them using the *final* file state (`self.controller._files()`). If the controller correctly mutated any source files after an earlier test, the tree hash verification fails, crashing valid T-route cells at completion.",
      "fix": "Fetch the corresponding historical file state from the controller case history for each specific test, or only verify the final test, instead of applying the mutated final file state to all past test receipts."
    }
  ],
  "limitations": [
    "Pending integration of full campaign admission and native generation capabilities.",
    "Pending complete rubrics, frozen sources, images, and common budget definitions.",
    "Pending worst-context validation and final export delivery mechanics."
  ],
  "tests_executed": false
}
